from pathlib import Path
import hashlib,json,subprocess
root=Path('artifacts/source-drive-study/escalation/native')
def read(n):return json.loads((root/n).read_text())
film=read('route-investigation.json');session=read('route-investigation-session.json');arrival=read('arrival-state.json');restored=read('restored-arrival-state.json');finished=read('finish-study-state.json');take=arrival['takes'][0]
