events=arrival['events'];hits=[e for e in events if e['type']=='physical-road-joint'];broadcast=[e for e in events if e['type']=='broadcast-joint-fingerprint'];play=[e for e in events if e['type']=='tape-play'];stop=[e for e in events if e['type']=='tape-stop'];pull=read('pull-in-state.json')
def packets(name):
 data=json.loads(subprocess.check_output(['/opt/homebrew/bin/ffprobe','-v','error','-show_packets','-show_data_hash','sha256','-show_entries','packet=stream_index,pts_time,dts_time,data_hash','-of','json',str(root/name)]));return data['packets']
p,q=packets('route-investigation.webm'),packets('route-investigation-review.webm');payload=lambda xs:{i:[r['data_hash'] for r in xs if r['stream_index']==i] for i in {r['stream_index'] for r in xs}}
