checks={'noBrowserErrors':not session['errors'] and not arrival['errors'],'noSourceDriftDuringContinuousRun':not drift,'beginsAtEntry':film['initial']['furthest']==0,'continuousFixtureFree':not any(c['op']=='fixture' for c in session['commands'][4:session['commands'].index(next(c for c in session['commands'] if c['op']=='stop'))]),'driverOnlyOrdinaryKeyboard':all(r['noStateMutationDuringSegment'] for r in route),'oneServicePrediction':len(broadcast)==1 and broadcast[0]['audible'],'sixActualAxleContacts':len(hits)==6,'predictionPrecedesCrossing':len(hits)==6 and broadcast[0]['t']<hits[0]['t'],'realTakeHasDecodedDuration':take['durationIntegrity']=='decoded-sample-count' and take['duration']>29,'livePhysicalPlaybackUsed':len(play)==1 and any(e['type']=='tape-playback' and e['mode']=='physical-recorder-speaker' for e in arrival['audio']['events']),'stopRetainsResponsiveWorld':len(stop)>=2,'manualArrivalAfterDriving':arrival['arrived'] and arrival['furthest']>=1194 and abs(arrival['speed'])<.4,'restoreIsStoppedPaused':restored['arrived'] and restored['paused'] and restored['speed']==0,'weatherRestored':restored['weather']==read('finish-study-state.json')['weather'],'explicitFinishOnly':finished.get('finished') and finished['paused'] and any(e['type']=='study-return-request' for e in finished['events']),'remuxPreservesStreamPayloads':payload(p)==payload(q)}
report={'kind':'continuous-revised-route-technical-inspection','scope':'Ordinary route before later exterior-radiance correction; no horror direction installed. Scripted keyboard technical driver, not human acceptance.','movieSeconds':float(probe['format']['duration']),'arrivalDistanceM':arrival['furthest'],'takeSeconds':take['duration'],'takeSha256':hashlib.sha256((root/'bridge-field-take.webm').read_bytes()).hexdigest(),'forecastLeadSeconds':hits[0]['t']-broadcast[0]['t'],'routeGeometrySha256':arrival['geometrySha256'],'sourceDrift':drift,'timing':film['timing'],'pullIn':{'distance':pull['furthest'],'speed':pull['speed'],'surface':pull['surface'],'roadOffset':pull['roadOffset'],'limitation':'The scripted pull-in segment did not stop before playback; it crossed the shoulder and remained moving. This is not stopped-bay or human parking acceptance.'},'renderLimit':'This continuous run exposed missing exterior sky exposure and outlined glass beads. Fixed views after the source-radiance correction are separate; this movie does not prove that later rendering.','productionReturn':'finish-study-state records the proposed grey-door exterior return; the production route/save handoff remains uninstalled.','humanValidation':'pending fresh players and independent review; no claim of dread, material recognition, comfort or 8–10 minute pacing.','checks':checks,'passed':all(checks.values())}
